    where q.exam_source = 'AI-generated-board-seed'
      and q.board_specialty = 'family_medicine'
      and q.scenario = 'ผู้ป่วยอายุ 60 ปี — recent death of spouse × 2 mo + sleep + appetite + sadness + isolation; family worried'
  );

